typedef unsigned int u_int;
typedef struct {
    u_int d4madr;
    u_int d4tadr;
    u_int d4qwc;
    u_int d4chcr;
    u_int d3madr;
    u_int d3qwc;
    u_int d3chcr;
    u_int ipubp;
    u_int ipuctrl;
} sceIpuDmaEnv;
typedef unsigned long long u_long;
typedef u_long u_long128 __attribute__((mode(TI)));
typedef struct {
    u_long128 *data;
    u_long128 *tag;
    int n;
    int dmaStart;
    int dmaN;
    int readBytes;
    int buffSize;
    sceIpuDmaEnv env;
    int sema;
    int isActive;
    long totalBytes;
    void *ts;
    int n_ts;
    int count_ts;
    int wt_ts;
} ViBuf;

#define VIBUF_ELM_SIZE 2048
#define DMA_ID_REFE 0
#define DMA_ID_REF 3
#define TAG_ADDR(i) ((u_int)DmaAddr(f->tag + i))
#define DATA_ADDR(i) ((u_int)f->data + VIBUF_ELM_SIZE * (i))
#define WRAP_ADDR(addr) ((u_int)(f->data) + (((u_int)(addr) - (u_int)(f->data)) % (VIBUF_ELM_SIZE * f->n)))
#define IsInRegion(i,start,len,n) ((0 <= (((i)+(n)-(start))%(n))) && ((((i)+(n)-(start))%(n)) < (len)))
#define DmaAddr(val) ((void *)((u_int)(val) & 0x0fffffff))
#define sceIpuIsBusy() (*IPU_CTRL & 0x80000000)
#define sceIpuBCLR(bp) (*IPU_CMD = 0x40000000 | (bp))

static volatile u_int *const D3_MADR = (u_int *)0x1000B010;
static volatile u_int *const D3_QWC = (u_int *)0x1000B020;
static volatile u_int *const D4_MADR = (u_int *)0x1000B410;
static volatile u_int *const D4_QWC = (u_int *)0x1000B420;
static volatile u_int *const D4_TADR = (u_int *)0x1000B430;
static volatile u_int *const IPU_CMD = (u_int *)0x10002000;
static volatile u_int *const IPU_CTRL = (u_int *)0x10002010;
extern "C" int WaitSema(int);
extern "C" int SignalSema(int);
static int getFIFOindex(ViBuf *, void *);
static void setD3_CHCR(u_int);
static void setD4_CHCR(u_int);
__asm__(".equ WaitSema, 0x003DB6A0");
__asm__(".equ SignalSema, 0x003DB680");
__asm__(".equ getFIFOindex__FP5ViBufPv, 0x00389DB0");
__asm__(".equ setD3_CHCR__FUi, 0x00389DF8");
__asm__(".equ setD4_CHCR__FUi, 0x00389E68");

static int viBufRestartDMA( ViBuf* f )
{
    int     bp, fp, ifc, index, index_next, id;
    u_int   d4madr_next, d4qwc_next, d4tadr_next, d4chcr_next;

    WaitSema( f->sema );
    bp = f->env.ipubp & 0x7f;
    fp = ( f->env.ipubp >> 16 ) & 0x3;
    ifc = ( f->env.ipubp >> 8 ) & 0xf;
    d4madr_next = f->env.d4madr - ( (fp + ifc) << 4 );
    d4qwc_next = f->env.d4qwc + ( fp + ifc );
    d4tadr_next = f->env.d4tadr;
    d4chcr_next = f->env.d4chcr | 0x100;
    if( d4madr_next < (u_int)f->data )
    {
        d4qwc_next = ( DATA_ADDR(0) - d4madr_next ) >> 4;
        d4madr_next += (u_int)( f->n * VIBUF_ELM_SIZE );
        d4tadr_next = TAG_ADDR( 0 );
        id = ( f->env.d4madr == DATA_ADDR(0) || f->env.d4madr == DATA_ADDR(f->n) )? DMA_ID_REFE : DMA_ID_REF;
        d4chcr_next = (f->env.d4chcr & 0x0fffffff) | (id << 28) | 0x100;
        if( !IsInRegion(0, f->dmaStart, f->dmaN, f->n) )
        {
            f->dmaStart = f->n - 1;
            f->dmaN++;
        }
    }
    else if( (index = getFIFOindex(f, (void*)f->env.d4madr)) != (index_next = getFIFOindex(f, (void*)d4madr_next)) )
    {
        d4tadr_next = TAG_ADDR( index );
        d4qwc_next = ( DATA_ADDR(index) - d4madr_next ) >> 4;
        id = ( WRAP_ADDR(f->env.d4madr) == DATA_ADDR((f->dmaStart + f->dmaN) % f->n) )? DMA_ID_REFE : DMA_ID_REF;
        d4chcr_next = ( f->env.d4chcr & 0x0fffffff ) | (id << 28) | 0x100;
        if( !IsInRegion(index_next, f->dmaStart, f->dmaN, f->n) )
        {
            f->dmaStart = index_next;
            f->dmaN++;
        }
    }
    if( f->env.d3madr && f->env.d3qwc )
    {
        *D3_MADR = f->env.d3madr;
        *D3_QWC  = f->env.d3qwc;
        setD3_CHCR( f->env.d3chcr | 0x100 );
    }
    if( f->dmaN )
    {
        while( sceIpuIsBusy() )
            ;
        sceIpuBCLR( bp );
        while( sceIpuIsBusy() )
            ;
    }
    *D4_MADR = d4madr_next;
    *D4_TADR = d4tadr_next;
    *D4_QWC  = d4qwc_next;
    if( f->dmaN )
    {
        setD4_CHCR( d4chcr_next );
    }
    *IPU_CTRL = f->env.ipuctrl;
    f->isActive = 1;
    SignalSema(f->sema);
    return true;
}
__asm__(".globl viBufRestartDMA__FP5ViBuf");
